INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$6762772f$SATQ$, $SATQ$ed0c6123-ffe9-4c37-9b48-dfe7c470ff88$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Artificial leaves are a developing renewable energy technology that mimics the process of photosynthesis in plants. These devices are silicon-based solar cells coated in chemical catalysts that activate reactions that split water molecules into hydrogen and oxygen gas. The technology, while generating lots of interest, is not yet commercially viable as a large-scale energy source. To meet this challenge, scientists from many fields are researching ways to store, transport, and distribute the energy the devices produce while other scientists are working to improve the cost and efficiency of the devices. &nbsp;</p>$SATQ$, $SATQ$<p>Which choice best states the main idea of the text?</p>$SATQ$, $SATQ$[{"id":"e5e4889c-2a25-4780-99a5-f5d71a1c0645","content":"<p>Continued research and development in artificial-leaf technology is needed before the devices can be widely used as an energy source.&nbsp;</p>"},{"id":"5c6a122f-6471-4875-84eb-748c272d5774","content":"<p>The recent increase in the commercial use of artificial leaves as an energy source has encouraged many scientists to research ways to improve the technology.&nbsp;</p>"},{"id":"6212d7fd-a091-457f-9d6b-9cc640d3c283","content":"<p>Artificial leaves split water molecules into oxygen and hydrogen gas using catalysts more efficiently than plants do using the process of photosynthesis.</p>"},{"id":"19457871-fa6f-4fa5-8b63-55c16aaf2ca8","content":"<p>Artificial leaves were developed to mimic the natural process of photosynthesis in plants in order to store energy for long-term commercial use.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["e5e4889c-2a25-4780-99a5-f5d71a1c0645"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately states the main idea of the text. According to the text, artificial leaves are a renewable energy technology that&rsquo;s in development and generating interest. The text goes on to state that artificial-leaf technology "is not yet commercially viable as a large-scale energy source" and that scientists from several fields are doing additional research to refine the technology. Thus, the main idea is that continued research and development in artificial-leaf technology is needed before the devices can be widely used as an energy source.</p><p>Choice B is incorrect. While the text does state that scientists from many fields are researching artificial leaves, they&rsquo;re doing so to address the fact that the leaves are not yet commercially viable, rather than in response to an increase in commercial use. Choice C is incorrect. Although the text does explain that artificial leaves help split water molecules into oxygen and hydrogen gas using catalysts, it doesn&rsquo;t argue that this process is more efficient than photosynthesis. This is merely a detail of the text and not the main idea, which is about the additional research needed to improve the cost and efficiency of these artificial leaves. Choice D is incorrect. Although the text indicates that artificial leaves mimic photosynthesis in plants, this is an incidental detail in support of the main idea that additional research is needed to make artificial leaves commercially viable.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6762772f","external_id":"ed0c6123-ffe9-4c37-9b48-dfe7c470ff88","vaultid":null,"uId":"e0ecdcd6-81e1-433c-9d0f-7f4225f04b49","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Artificial leaves are a developing renewable energy technology that mimics the process of photosynthesis in plants. These devices are silicon-based solar cells coated in chemical catalysts that activate reactions that split water molecules into hydrogen and oxygen gas. The technology, while generating lots of interest, is not yet commercially viable as a large-scale energy source. To meet this challenge, scientists from many fields are researching ways to store, transport, and distribute the energy the devices produce while other scientists are working to improve the cost and efficiency of the devices. &nbsp;</p>","stem":"<p>Which choice best states the main idea of the text?</p>","answerOptions":[{"id":"e5e4889c-2a25-4780-99a5-f5d71a1c0645","content":"<p>Continued research and development in artificial-leaf technology is needed before the devices can be widely used as an energy source.&nbsp;</p>"},{"id":"5c6a122f-6471-4875-84eb-748c272d5774","content":"<p>The recent increase in the commercial use of artificial leaves as an energy source has encouraged many scientists to research ways to improve the technology.&nbsp;</p>"},{"id":"6212d7fd-a091-457f-9d6b-9cc640d3c283","content":"<p>Artificial leaves split water molecules into oxygen and hydrogen gas using catalysts more efficiently than plants do using the process of photosynthesis.</p>"},{"id":"19457871-fa6f-4fa5-8b63-55c16aaf2ca8","content":"<p>Artificial leaves were developed to mimic the natural process of photosynthesis in plants in order to store energy for long-term commercial use.</p>"}],"keys":["e5e4889c-2a25-4780-99a5-f5d71a1c0645"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately states the main idea of the text. According to the text, artificial leaves are a renewable energy technology that&rsquo;s in development and generating interest. The text goes on to state that artificial-leaf technology \"is not yet commercially viable as a large-scale energy source\" and that scientists from several fields are doing additional research to refine the technology. Thus, the main idea is that continued research and development in artificial-leaf technology is needed before the devices can be widely used as an energy source.</p><p>Choice B is incorrect. While the text does state that scientists from many fields are researching artificial leaves, they&rsquo;re doing so to address the fact that the leaves are not yet commercially viable, rather than in response to an increase in commercial use. Choice C is incorrect. Although the text does explain that artificial leaves help split water molecules into oxygen and hydrogen gas using catalysts, it doesn&rsquo;t argue that this process is more efficient than photosynthesis. This is merely a detail of the text and not the main idea, which is about the additional research needed to improve the cost and efficiency of these artificial leaves. Choice D is incorrect. Although the text indicates that artificial leaves mimic photosynthesis in plants, this is an incidental detail in support of the main idea that additional research is needed to make artificial leaves commercially viable.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323041,"updateDate":1730147323041}$SATQ$::jsonb, 1730147323041, 1730147323041),
    ($SATQ$67b59a67$SATQ$, $SATQ$29e2e0fc-8844-490c-85f3-24338f917e2a$SATQ$::uuid, $SATQ$26030e53-a477-4b45-af33-76181714597f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Plants like potatoes, tomatoes, and soybeans are susceptible to bacterial wilt disease caused by the bacteria <em>Ralstonia solanacearum</em>. A multinational team of scientists led by Zhong Wei studied whether other microbes in the soil might influence the degree to which plants are affected by the disease. The team sampled soil surrounding individual tomato plants over time and compared the results of plants that became diseased with those that remained healthy. They concluded that the presence of certain microbes in the soil might explain the difference between healthy and diseased plants.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support the team&rsquo;s conclusion?</p>$SATQ$, $SATQ$[{"id":"065dca5d-520f-4d6d-86e7-fa19b97e0bb7","content":"<p>The soil surrounding healthy plants contained significantly higher concentrations of microbes known to inhibit <em>Ralstonia solanacearum</em> than the soil surrounding diseased plants did.</p>"},{"id":"95a5cb8d-0a91-4541-a959-11e2f7b1ea76","content":"<p>The soil surrounding the plants contained high concentrations of <em>Ralstonia solanacearum</em> regardless of whether the plants were affected by wilt disease.</p>"},{"id":"ac67c233-0bf4-4c60-9fb9-3de1f6644bfa","content":"<p>The soil surrounding healthy plants tended to have significantly higher moisture levels than the soil surrounding diseased plants did.&nbsp;</p>"},{"id":"2188bd15-c36a-4909-aa8e-0b14b3f8333e","content":"<p>By the end of the experiment, over half the plants had been affected by wilt disease regardless of differences in the types and concentrations of microbes in the surrounding soil.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["065dca5d-520f-4d6d-86e7-fa19b97e0bb7"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. This choice provides evidence that directly links the presence of <em>R</em>. <em>solanacearum</em>-inhibiting microbes in the soil to the health of tomato plants. </p><p>Choice B is incorrect. This choice would weaken the team&rsquo;s conclusion. It suggests that the presence of the disease-causing bacteria had no effect on the health of the tomato plants. Choice C is incorrect. This choice doesn&rsquo;t support the team&rsquo;s conclusion. The conclusion is about microbes, not soil moisture. Choice D is incorrect. This choice would weaken the team&rsquo;s conclusion. It suggests that the presence of the bacteria-inhibiting microbe in soil had no effect on the health of the tomato plants. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-M009$SATQ$, $SATQ$$SATQ$, $SATQ$7baa9437-0b59-4bbd-8af2-abc8ac01671b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"67b59a67","external_id":"29e2e0fc-8844-490c-85f3-24338f917e2a","vaultid":"26030e53-a477-4b45-af33-76181714597f","uId":"2d2f905c-635c-461c-ba3e-986f48104d1c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Plants like potatoes, tomatoes, and soybeans are susceptible to bacterial wilt disease caused by the bacteria <em>Ralstonia solanacearum</em>. A multinational team of scientists led by Zhong Wei studied whether other microbes in the soil might influence the degree to which plants are affected by the disease. The team sampled soil surrounding individual tomato plants over time and compared the results of plants that became diseased with those that remained healthy. They concluded that the presence of certain microbes in the soil might explain the difference between healthy and diseased plants.</p>","stem":"<p>Which finding, if true, would most directly support the team&rsquo;s conclusion?</p>","answerOptions":[{"id":"065dca5d-520f-4d6d-86e7-fa19b97e0bb7","content":"<p>The soil surrounding healthy plants contained significantly higher concentrations of microbes known to inhibit <em>Ralstonia solanacearum</em> than the soil surrounding diseased plants did.</p>"},{"id":"95a5cb8d-0a91-4541-a959-11e2f7b1ea76","content":"<p>The soil surrounding the plants contained high concentrations of <em>Ralstonia solanacearum</em> regardless of whether the plants were affected by wilt disease.</p>"},{"id":"ac67c233-0bf4-4c60-9fb9-3de1f6644bfa","content":"<p>The soil surrounding healthy plants tended to have significantly higher moisture levels than the soil surrounding diseased plants did.&nbsp;</p>"},{"id":"2188bd15-c36a-4909-aa8e-0b14b3f8333e","content":"<p>By the end of the experiment, over half the plants had been affected by wilt disease regardless of differences in the types and concentrations of microbes in the surrounding soil.&nbsp;</p>"}],"keys":["065dca5d-520f-4d6d-86e7-fa19b97e0bb7"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. This choice provides evidence that directly links the presence of <em>R</em>. <em>solanacearum</em>-inhibiting microbes in the soil to the health of tomato plants. </p><p>Choice B is incorrect. This choice would weaken the team&rsquo;s conclusion. It suggests that the presence of the disease-causing bacteria had no effect on the health of the tomato plants. Choice C is incorrect. This choice doesn&rsquo;t support the team&rsquo;s conclusion. The conclusion is about microbes, not soil moisture. Choice D is incorrect. This choice would weaken the team&rsquo;s conclusion. It suggests that the presence of the bacteria-inhibiting microbe in soil had no effect on the health of the tomato plants. </p>","parenttemplatename":"OSP-KA-TXT-M009","parenttemplateid":"","templateclusterid":"7baa9437-0b59-4bbd-8af2-abc8ac01671b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959377,"updateDate":1691007959377}$SATQ$::jsonb, 1691007959377, 1691007959377),
    ($SATQ$69d662af$SATQ$, $SATQ$e807e311-35fb-41ba-a60b-feebda8114ab$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Ann Petry&rsquo;s 1946 novel <em>The Street</em>. Lutie lives in an apartment in Harlem, New York.</p>
<blockquote>
<p>The glow from the sunset was making the street radiant. The street is nice in this light, [Lutie] thought. It was swarming with children who were playing ball and darting back and forth across the sidewalk in complicated games of tag. Girls were skipping double dutch rope, going tirelessly through the exact center of a pair of ropes, jumping first on one foot and then the other.</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;1946 by Ann Petry</span></p>$SATQ$, $SATQ$<p>Which choice best describes what is happening in the text?</p>$SATQ$, $SATQ$[{"id":"392ea73f-95fd-4412-b52b-89309238e2bb","content":"<p>Lutie is observing the appearance of the street at a particular time of day and the events occurring on it.</p>"},{"id":"2d0c434c-ef90-4b1d-a574-6a3cfbc50a8c","content":"<p>Lutie is annoyed by the noise of children playing games on her street.</p>"},{"id":"5590c57b-8931-44bc-8cfa-936e5bbe525d","content":"<p>Lutie is puzzled by the rules of certain children&rsquo;s games.</p>"},{"id":"5f4a3ec4-96dd-471a-8598-5703d45ab1f9","content":"<p>Lutie is spending time alone in her apartment because she doesn&rsquo;t want to interact with her neighbors.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["392ea73f-95fd-4412-b52b-89309238e2bb"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately states what is happening in the text. The narrator notes that Lutie thinks the street looks nice in the light of the sunset. The narrator goes on to describe what Lutie can see in the street: children playing ball or tag and girls skipping rope. Thus, what is happening in the text is that Lutie is observing the appearance of the street at a particular time of day and the events occurring on it.</p><p>Choice B is incorrect. Although Lutie is observing children playing games on her street, the text doesn&rsquo;t suggest that she is annoyed by the noise of the games. Instead, the text says that Lutie thinks the street looks nice in the light of the sunset. Choice C is incorrect. Although Lutie is observing children playing games on her street, the text doesn&rsquo;t suggest that she is puzzled by the rules of the games. Choice D is incorrect because there is no evidence in the text that Lutie doesn&rsquo;t want to interact with her neighbors or that she is in her apartment alone. All the text indicates about Lutie is that she is watching the events on the street and thinks the street looks nice in the light of the sunset.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"69d662af","external_id":"e807e311-35fb-41ba-a60b-feebda8114ab","vaultid":null,"uId":"6889c53b-e0f4-4970-a349-974463b8b23c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is adapted from Ann Petry&rsquo;s 1946 novel <em>The Street</em>. Lutie lives in an apartment in Harlem, New York.</p>\n<blockquote>\n<p>The glow from the sunset was making the street radiant. The street is nice in this light, [Lutie] thought. It was swarming with children who were playing ball and darting back and forth across the sidewalk in complicated games of tag. Girls were skipping double dutch rope, going tirelessly through the exact center of a pair of ropes, jumping first on one foot and then the other.</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;1946 by Ann Petry</span></p>","stem":"<p>Which choice best describes what is happening in the text?</p>","answerOptions":[{"id":"392ea73f-95fd-4412-b52b-89309238e2bb","content":"<p>Lutie is observing the appearance of the street at a particular time of day and the events occurring on it.</p>"},{"id":"2d0c434c-ef90-4b1d-a574-6a3cfbc50a8c","content":"<p>Lutie is annoyed by the noise of children playing games on her street.</p>"},{"id":"5590c57b-8931-44bc-8cfa-936e5bbe525d","content":"<p>Lutie is puzzled by the rules of certain children&rsquo;s games.</p>"},{"id":"5f4a3ec4-96dd-471a-8598-5703d45ab1f9","content":"<p>Lutie is spending time alone in her apartment because she doesn&rsquo;t want to interact with her neighbors.</p>"}],"keys":["392ea73f-95fd-4412-b52b-89309238e2bb"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately states what is happening in the text. The narrator notes that Lutie thinks the street looks nice in the light of the sunset. The narrator goes on to describe what Lutie can see in the street: children playing ball or tag and girls skipping rope. Thus, what is happening in the text is that Lutie is observing the appearance of the street at a particular time of day and the events occurring on it.</p><p>Choice B is incorrect. Although Lutie is observing children playing games on her street, the text doesn&rsquo;t suggest that she is annoyed by the noise of the games. Instead, the text says that Lutie thinks the street looks nice in the light of the sunset. Choice C is incorrect. Although Lutie is observing children playing games on her street, the text doesn&rsquo;t suggest that she is puzzled by the rules of the games. Choice D is incorrect because there is no evidence in the text that Lutie doesn&rsquo;t want to interact with her neighbors or that she is in her apartment alone. All the text indicates about Lutie is that she is watching the events on the street and thinks the street looks nice in the light of the sunset.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323035,"updateDate":1730147323035}$SATQ$::jsonb, 1730147323035, 1730147323035),
    ($SATQ$6a6bbac3$SATQ$, $SATQ$15e61784-d141-4360-95ad-6de4a72b0a0d$SATQ$::uuid, $SATQ$db042d55-9e5e-462c-a60e-8fc69d801474$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Number and Origin of Clamshell Tools Found at Different Levels Below the Surface in Neanderthal Cave</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Depth of tools found below surface in cave (meters)</th><th scope="col" style="text-align: center; vertical-align: bottom;">Clamshells that Neanderthals collected from the beach</th><th scope="col" style="text-align: center; vertical-align: bottom;">Clamshells that Neanderthals harvested from the seafloor</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">3&ndash;4</th><td style="text-align: center;">99</td><td style="text-align: center;">33</td></tr><tr><th scope="row" style="text-align: left;">6&ndash;7</th><td style="text-align: center;">1</td><td style="text-align: center;">0</td></tr><tr><th scope="row" style="text-align: left;">4&ndash;5</th><td style="text-align: center;">2</td><td style="text-align: center;">0</td></tr><tr><th scope="row" style="text-align: left;">2&ndash;3</th><td style="text-align: center;">7</td><td style="text-align: center;">0</td></tr><tr><th scope="row" style="text-align: left;">5&ndash;6</th><td style="text-align: center;">18</td><td style="text-align: center;">7</td></tr></tbody></table></figure></p>
<p>Studying tools unearthed at a cave site on the western coast of Italy, archaeologist Paola Villa and colleagues have determined that prehistoric Neanderthal groups fashioned them from shells of clams that they harvested from the seafloor while wading or diving or that washed up on the beach. Clamshells become thin and eroded as they wash up on the beach, while those on the seafloor are smooth and sturdy, so the research team suspects that Neanderthals prized the tools made with seafloor shells. However, the team also concluded that those tools were likely more challenging to obtain, noting that <span aria-hidden="true">______</span><span class="sr-only">blank</span> </p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to support the research team&rsquo;s conclusion?</p>$SATQ$, $SATQ$[{"id":"9a842430-300d-485b-b509-5c6089cb65b1","content":"<p>at each depth below the surface in the cave, the difference in the numbers of tools of each type suggests that shells were easier to collect from the beach than to harvest from the seafloor.&nbsp;</p>"},{"id":"b5010922-e356-4335-8d24-b2408bc7bd8e","content":"<p>the highest number of tools were at a depth of 3&ndash;4 meters below the surface, which suggests that the Neanderthal population at the site was highest during the related period of time.</p>"},{"id":"f5d41b47-44b8-4f87-96da-a00d26658ed3","content":"<p>at each depth below the surface in the cave, the difference in the numbers of tools of each type suggests that Neanderthals preferred to use clamshells from the beach because of their durability.</p>"},{"id":"4cc598b2-03d5-43b2-ad02-a60bd56c8891","content":"<p>the higher number of tools at depths of 5&ndash;6 meters below the surface in the cave than at depths of 4&ndash;5 meters below the surface suggests that the size of clam populations changed over time.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["9a842430-300d-485b-b509-5c6089cb65b1"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most effectively uses data from the table to support the researchers&rsquo; conclusion about the harvesting of clamshells by Neanderthals for use as tools. The text explains that Neanderthals used clamshells to make tools and that the sturdiest, and therefore the most desirable, shells for this purpose are found on the seafloor, not on the beach. However, the researchers also concluded that the clamshell tools made from shells from the seafloor are rarer than those made from shells from the beach. Meanwhile the table shows that at each depth, the number of tools made from shells from the beach exceeds the number made from the more desirable shells from the seafloor. The fact that the more desirable shells are less common suggests that it was significantly more difficult to harvest shells from the seafloor than from the beach. </p><p>Choice B is incorrect because knowing which depth represents the period of time with the highest Neanderthal population does not help answer the question of why the Neanderthals consistently made more tools from the less desirable shells from the beach than they made from the more desirable shells from the seafloor. Choice C is incorrect because it claims that the beach shells are more durable than the seafloor shells, which contradicts the text&rsquo;s description of shells from the seafloor as smoother and sturdier than shells from the beach. Choice D is incorrect because knowing which depth has the most artifacts or whether the clam population fluctuated does not help explain why tools made from the less desirable shells from the beach outnumber tools made from the more desirable shells from the seafloor. </p>$SATQ$, false, 0, $SATQ$OSP-527-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$fb2695d2-2f29-4b64-b2e8-d945f23723ce$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6a6bbac3","external_id":"15e61784-d141-4360-95ad-6de4a72b0a0d","vaultid":"db042d55-9e5e-462c-a60e-8fc69d801474","uId":"196ad555-4d23-4bb9-955e-9ffd19ceaa6c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Number and Origin of Clamshell Tools Found at Different Levels Below the Surface in Neanderthal Cave</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Depth of tools found below surface in cave (meters)</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Clamshells that Neanderthals collected from the beach</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Clamshells that Neanderthals harvested from the seafloor</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">3&ndash;4</th><td style=\"text-align: center;\">99</td><td style=\"text-align: center;\">33</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">6&ndash;7</th><td style=\"text-align: center;\">1</td><td style=\"text-align: center;\">0</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">4&ndash;5</th><td style=\"text-align: center;\">2</td><td style=\"text-align: center;\">0</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">2&ndash;3</th><td style=\"text-align: center;\">7</td><td style=\"text-align: center;\">0</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">5&ndash;6</th><td style=\"text-align: center;\">18</td><td style=\"text-align: center;\">7</td></tr></tbody></table></figure></p>\n<p>Studying tools unearthed at a cave site on the western coast of Italy, archaeologist Paola Villa and colleagues have determined that prehistoric Neanderthal groups fashioned them from shells of clams that they harvested from the seafloor while wading or diving or that washed up on the beach. Clamshells become thin and eroded as they wash up on the beach, while those on the seafloor are smooth and sturdy, so the research team suspects that Neanderthals prized the tools made with seafloor shells. However, the team also concluded that those tools were likely more challenging to obtain, noting that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> </p>","stem":"<p>Which choice most effectively uses data from the table to support the research team&rsquo;s conclusion?</p>","answerOptions":[{"id":"9a842430-300d-485b-b509-5c6089cb65b1","content":"<p>at each depth below the surface in the cave, the difference in the numbers of tools of each type suggests that shells were easier to collect from the beach than to harvest from the seafloor.&nbsp;</p>"},{"id":"b5010922-e356-4335-8d24-b2408bc7bd8e","content":"<p>the highest number of tools were at a depth of 3&ndash;4 meters below the surface, which suggests that the Neanderthal population at the site was highest during the related period of time.</p>"},{"id":"f5d41b47-44b8-4f87-96da-a00d26658ed3","content":"<p>at each depth below the surface in the cave, the difference in the numbers of tools of each type suggests that Neanderthals preferred to use clamshells from the beach because of their durability.</p>"},{"id":"4cc598b2-03d5-43b2-ad02-a60bd56c8891","content":"<p>the higher number of tools at depths of 5&ndash;6 meters below the surface in the cave than at depths of 4&ndash;5 meters below the surface suggests that the size of clam populations changed over time.</p>"}],"keys":["9a842430-300d-485b-b509-5c6089cb65b1"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most effectively uses data from the table to support the researchers&rsquo; conclusion about the harvesting of clamshells by Neanderthals for use as tools. The text explains that Neanderthals used clamshells to make tools and that the sturdiest, and therefore the most desirable, shells for this purpose are found on the seafloor, not on the beach. However, the researchers also concluded that the clamshell tools made from shells from the seafloor are rarer than those made from shells from the beach. Meanwhile the table shows that at each depth, the number of tools made from shells from the beach exceeds the number made from the more desirable shells from the seafloor. The fact that the more desirable shells are less common suggests that it was significantly more difficult to harvest shells from the seafloor than from the beach. </p><p>Choice B is incorrect because knowing which depth represents the period of time with the highest Neanderthal population does not help answer the question of why the Neanderthals consistently made more tools from the less desirable shells from the beach than they made from the more desirable shells from the seafloor. Choice C is incorrect because it claims that the beach shells are more durable than the seafloor shells, which contradicts the text&rsquo;s description of shells from the seafloor as smoother and sturdier than shells from the beach. Choice D is incorrect because knowing which depth has the most artifacts or whether the clam population fluctuated does not help explain why tools made from the less desirable shells from the beach outnumber tools made from the more desirable shells from the seafloor. </p>","parenttemplatename":"OSP-527-QUA","parenttemplateid":"","templateclusterid":"fb2695d2-2f29-4b64-b2e8-d945f23723ce","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959338,"updateDate":1691007959338}$SATQ$::jsonb, 1691007959338, 1691007959338),
