14423076923" fill="#666666" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="124.13341346153845" y="260.8888888888889" height="11.11111111111111" width="23.71514423076923" fill="#CCCCCC" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="147.84855769230768" y="249.77777777777777" height="22.22222222222222" width="23.71514423076923" fill="#000000" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="end" transform="translate(145.91098557692305 291.84) rotate(-40)" fill="#000000" font-size="19.84" font-family="Crimson Text">male</text><rect xmlns="http://www.w3.org/2000/svg" x="195.27884615384613" y="127.55555555555557" height="144.44444444444443" width="23.71514423076923" fill="#666666" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="218.99399038461536" y="249.77777777777777" height="22.22222222222222" width="23.71514423076923" fill="#CCCCCC" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="242.70913461538458" y="260.8888888888889" height="11.11111111111111" width="23.71514423076923" fill="#000000" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="end" transform="translate(240.77156249999996 291.84) rotate(-40)" fill="#000000" font-size="19.84" font-family="Crimson Text">female</text><rect xmlns="http://www.w3.org/2000/svg" x="290.13942307692304" y="272" height="0" width="23.71514423076923" fill="#666666" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="313.85456730769226" y="238.66666666666669" height="33.33333333333333" width="23.71514423076923" fill="#CCCCCC" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="337.5697115384615" y="105.33333333333334" height="166.66666666666666" width="23.71514423076923" fill="#000000" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="end" transform="translate(335.63213942307686 291.84) rotate(-40)" fill="#000000" font-size="19.84" font-family="Crimson Text">undetermined</text><text text-anchor="middle" transform="translate(230.8515625 24)" fill="#000000" font-size="19.84" font-family="Crimson Text">Banded Sand Catsharks Found in </text><text text-anchor="middle" transform="translate(230.8515625 48)" fill="#000000" font-size="19.84" font-family="Crimson Text">Three Sponges</text><rect xmlns="http://www.w3.org/2000/svg" fill="none" x="153.203125" y="413.682373046875" height="103" width="108.59375" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="160.203125" y="425.682373046875" height="12" width="12" fill="#666666" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><text transform="translate(182.203125 437.682373046875)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text"> sponge 1</text><rect xmlns="http://www.w3.org/2000/svg" x="160.203125" y="457.682373046875" height="12" width="12" fill="#CCCCCC" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><text transform="translate(182.203125 469.682373046875)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text"> sponge 2</text><rect xmlns="http://www.w3.org/2000/svg" x="160.203125" y="489.682373046875" height="12" width="12" fill="#000000" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><text transform="translate(182.203125 501.682373046875)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text"> sponge 3</text></g></svg></figure><div class="sr-only" role="region" aria-label="Long description for bar graph titled Banded Sand Catsharks Found in Three Sponges"><ul>
<li>For each data category, the following bars are shown:<br/>
<ul>
<li>sponge 1</li>
<li>sponge 2</li>
<li>sponge 3</li>
</ul>
</li>
<li>The Number of sharks data for the 3 categories are as follows:<br/>
<ul>
<li>male:<br/>
<ul>
<li>sponge 1: 17 sharks</li>
<li>sponge 2: 1 shark</li>
<li>sponge 3: 2 sharks</li>
</ul>
</li>
<li>female:&nbsp;<br/>
<ul>
<li>sponge 1: 13 sharks</li>
<li>sponge 2: 2 sharks</li>
<li>sponge 3: 1 shark</li>
</ul>
</li>
<li>undetermined:<br/>
<ul>
<li>sponge 1: 0 sharks</li>
<li>sponge 2: 3 sharks</li>
<li>sponge 3: 15 sharks</li>
</ul>
</li>
</ul>
</li>
</ul></div>
<p>Researcher Helen O&rsquo;Neill and her team were studying sponges in the family Irciniidae when they discovered that three of the sponges were functioning as microhabitats for banded sand catsharks (<em>Atelomycterus fasciatus</em>). Additionally, <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">the team found that male and female <em><span data-ssml-sub-alias="A">A.</span> fasciatus</em> share the same sponge (the same microhabitat)</span>, a behavior not found among Port Jackson sharks (<em>Heterodontus portusjacksoni</em>), another seabed-dwelling species.</p>$SATQ$, $SATQ$<p>Which choice best describes data from the graph that support the underlined claim?</p>$SATQ$, $SATQ$[{"id":"f9b847a1-2542-459d-a6bf-76fd222baae9","content":"<p>Each of the three sponges was inhabited by at least one male <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em> and at least one undetermined <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em>.</p>"},{"id":"f313710c-85a6-46b9-b28a-7f305c21a2d0","content":"<p>Sponge 1 was inhabited by 17 male <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em>.</p>"},{"id":"3d3630b6-2a6b-408b-80d9-71e92a3a4b1a","content":"<p>Each of the three sponges was inhabited by at least one male <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em> and at least one female <em>A. fasciatus</em>.</p>"},{"id":"3262dc73-3387-4e89-84fc-0fe7ed5cfa9d","content":"<p>Sponge 1 was inhabited by 13 female <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em>.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["3d3630b6-2a6b-408b-80d9-71e92a3a4b1a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it accurately describes data from the graph that support the claim that the team found that male and female <em>Atelomycterus fasciatus</em> (banded sand catsharks) share the same sponge. The graph presents the number of male, female, and undetermined banded sand catsharks found in each of three sponges&mdash;sponge 1, sponge 2, and sponge 3. The graph shows that approximately 17 male sharks and 13 female sharks were found in sponge 1, approximately 1 male shark and 2 female sharks were found in sponge 2, and approximately 2 male sharks and 1 female shark were found in sponge 3. Thus, the graph shows that male and female sharks were found sharing the same sponges.</p><p>Choice A is incorrect because the graph shows that one of the sponges (sponge 1) was <em>not</em> inhabited by any undetermined banded sand catsharks. Additionally, this choice doesn&rsquo;t give any information about female sharks, so it can&rsquo;t support the claim that male and female sharks are actually found in the same sponge. Choice B is incorrect because it doesn&rsquo;t give any information about female sharks. The graph does show that approximately 17 male banded sand catsharks inhabited sponge 1, but that information alone can&rsquo;t support the claim that male and female sharks are found in the same sponge. Choice D is incorrect because it doesn&rsquo;t give any information about male banded sand catsharks. The graph does show that approximately 13 female banded sand catsharks inhabited sponge 1, but that information alone can&rsquo;t support the claim that male and female sharks are found in the same sponge.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6af80ff3","external_id":"2d1c4edc-0ba2-479f-bac9-b3b060fa86f1","vaultid":null,"uId":"8efc7275-c7e6-4972-a48d-e67517c4bf74","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<figure class=\"image\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"400\" height=\"527.682373046875\" viewBox=\"0 0 400 527.682373046875\" role=\"img\" aria-label=\"Bar graph titled Banded Sand Catsharks Found in Three Sponges. The horizontal axis has no label. 3 data categories are shown. The vertical axis is labeled Number of sharks. It ranges from 0 to 18 in increments of 2. Refer to long description.\"><g id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\" data-name=\"Layer 1\"><defs>\n      <pattern id=\"bar4\" x=\"0\" y=\"0\" width=\"10\" height=\"100\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(50)\">\n        <rect x=\"0\" y=\"0\" width=\"5\" height=\"100\" fill=\"#CDCDCD\"/>\n        <rect x=\"5\" y=\"0\" width=\"5\" height=\"100\" fill=\"#444444\"/>\n      </pattern>\n    </defs><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"72\" x2=\"385\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"72\" x2=\"82.703125\" y2=\"72\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 78)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">18</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"94.22222222222223\" x2=\"385\" y2=\"94.22222222222223\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"94.22222222222223\" x2=\"82.703125\" y2=\"94.22222222222223\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 100.22222222222223)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">16</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"116.44444444444444\" x2=\"385\" y2=\"116.44444444444444\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"116.44444444444444\" x2=\"82.703125\" y2=\"116.44444444444444\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 122.44444444444444)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">14</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"138.66666666666666\" x2=\"385\" y2=\"138.66666666666666\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"138.66666666666666\" x2=\"82.703125\" y2=\"138.66666666666666\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 144.66666666666666)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">12</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"160.88888888888889\" x2=\"385\" y2=\"160.88888888888889\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"160.88888888888889\" x2=\"82.703125\" y2=\"160.88888888888889\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 166.88888888888889)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">10</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"183.11111111111111\" x2=\"385\" y2=\"183.11111111111111\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"183.11111111111111\" x2=\"82.703125\" y2=\"183.11111111111111\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 189.11111111111111)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">8</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"205.33333333333331\" x2=\"385\" y2=\"205.33333333333331\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"205.33333333333331\" x2=\"82.703125\" y2=\"205.33333333333331\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 211.33333333333331)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">6</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"227.55555555555554\" x2=\"385\" y2=\"227.55555555555554\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"227.55555555555554\" x2=\"82.703125\" y2=\"227.55555555555554\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 233.55555555555554)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">4</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"249.77777777777777\" x2=\"385\" y2=\"249.77777777777777\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"249.77777777777777\" x2=\"82.703125\" y2=\"249.77777777777777\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 255.77777777777777)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">2</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"272\" x2=\"385\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"272\" x2=\"82.703125\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-anchor=\"end\" transform=\"translate(64.703125 278)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">0</text><text text-anchor=\"middle\" transform=\"translate(24 172) rotate(-90)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Number of sharks</text><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"72\" x2=\"76.703125\" y2=\"272\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"100.41826923076923\" y=\"83.11111111111111\" height=\"188.88888888888889\" width=\"23.71514423076923\" fill=\"#666666\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"124.13341346153845\" y=\"260.8888888888889\" height=\"11.11111111111111\" width=\"23.71514423076923\" fill=\"#CCCCCC\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"147.84855769230768\" y=\"249.77777777777777\" height=\"22.22222222222222\" width=\"23.71514423076923\" fill=\"#000000\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(145.91098557692305 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">male</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"195.27884615384613\" y=\"127.55555555555557\" height=\"144.44444444444443\" width=\"23.71514423076923\" fill=\"#666666\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"218.99399038461536\" y=\"249.77777777777777\" height=\"22.22222222222222\" width=\"23.71514423076923\" fill=\"#CCCCCC\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"242.70913461538458\" y=\"260.8888888888889\" height=\"11.11111111111111\" width=\"23.71514423076923\" fill=\"#000000\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(240.77156249999996 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">female</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"290.13942307692304\" y=\"272\" height=\"0\" width=\"23.71514423076923\" fill=\"#666666\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"313.85456730769226\" y=\"238.66666666666669\" height=\"33.33333333333333\" width=\"23.71514423076923\" fill=\"#CCCCCC\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"337.5697115384615\" y=\"105.33333333333334\" height=\"166.66666666666666\" width=\"23.71514423076923\" fill=\"#000000\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text xmlns=\"http://www.w3.org/2000/svg\" x=\"0\" y=\"0\" text-anchor=\"end\" transform=\"translate(335.63213942307686 291.84) rotate(-40)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">undetermined</text><text text-anchor=\"middle\" transform=\"translate(230.8515625 24)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Banded Sand Catsharks Found in </text><text text-anchor=\"middle\" transform=\"translate(230.8515625 48)\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\">Three Sponges</text><rect xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" x=\"153.203125\" y=\"413.682373046875\" height=\"103\" width=\"108.59375\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"160.203125\" y=\"425.682373046875\" height=\"12\" width=\"12\" fill=\"#666666\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(182.203125 437.682373046875)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> sponge 1</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"160.203125\" y=\"457.682373046875\" height=\"12\" width=\"12\" fill=\"#CCCCCC\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(182.203125 469.682373046875)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> sponge 2</text><rect xmlns=\"http://www.w3.org/2000/svg\" x=\"160.203125\" y=\"489.682373046875\" height=\"12\" width=\"12\" fill=\"#000000\" stroke=\"#000000\" stroke-linejoin=\"mitre\" stroke-width=\"0.9\"/><text transform=\"translate(182.203125 501.682373046875)\" text-anchor=\"top\" fill=\"#000000\" font-size=\"19.84\" font-family=\"Crimson Text\"> sponge 3</text></g></svg></figure><div class=\"sr-only\" role=\"region\" aria-label=\"Long description for bar graph titled Banded Sand Catsharks Found in Three Sponges\"><ul>\n<li>For each data category, the following bars are shown:<br/>\n<ul>\n<li>sponge 1</li>\n<li>sponge 2</li>\n<li>sponge 3</li>\n</ul>\n</li>\n<li>The Number of sharks data for the 3 categories are as follows:<br/>\n<ul>\n<li>male:<br/>\n<ul>\n<li>sponge 1: 17 sharks</li>\n<li>sponge 2: 1 shark</li>\n<li>sponge 3: 2 sharks</li>\n</ul>\n</li>\n<li>female:&nbsp;<br/>\n<ul>\n<li>sponge 1: 13 sharks</li>\n<li>sponge 2: 2 sharks</li>\n<li>sponge 3: 1 shark</li>\n</ul>\n</li>\n<li>undetermined:<br/>\n<ul>\n<li>sponge 1: 0 sharks</li>\n<li>sponge 2: 3 sharks</li>\n<li>sponge 3: 15 sharks</li>\n</ul>\n</li>\n</ul>\n</li>\n</ul></div>\n<p>Researcher Helen O&rsquo;Neill and her team were studying sponges in the family Irciniidae when they discovered that three of the sponges were functioning as microhabitats for banded sand catsharks (<em>Atelomycterus fasciatus</em>). Additionally, <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">the team found that male and female <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em> share the same sponge (the same microhabitat)</span>, a behavior not found among Port Jackson sharks (<em>Heterodontus portusjacksoni</em>), another seabed-dwelling species.</p>","stem":"<p>Which choice best describes data from the graph that support the underlined claim?</p>","answerOptions":[{"id":"f9b847a1-2542-459d-a6bf-76fd222baae9","content":"<p>Each of the three sponges was inhabited by at least one male <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em> and at least one undetermined <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em>.</p>"},{"id":"f313710c-85a6-46b9-b28a-7f305c21a2d0","content":"<p>Sponge 1 was inhabited by 17 male <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em>.</p>"},{"id":"3d3630b6-2a6b-408b-80d9-71e92a3a4b1a","content":"<p>Each of the three sponges was inhabited by at least one male <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em> and at least one female <em>A. fasciatus</em>.</p>"},{"id":"3262dc73-3387-4e89-84fc-0fe7ed5cfa9d","content":"<p>Sponge 1 was inhabited by 13 female <em><span data-ssml-sub-alias=\"A\">A.</span> fasciatus</em>.</p>"}],"keys":["3d3630b6-2a6b-408b-80d9-71e92a3a4b1a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it accurately describes data from the graph that support the claim that the team found that male and female <em>Atelomycterus fasciatus</em> (banded sand catsharks) share the same sponge. The graph presents the number of male, female, and undetermined banded sand catsharks found in each of three sponges&mdash;sponge 1, sponge 2, and sponge 3. The graph shows that approximately 17 male sharks and 13 female sharks were found in sponge 1, approximately 1 male shark and 2 female sharks were found in sponge 2, and approximately 2 male sharks and 1 female shark were found in sponge 3. Thus, the graph shows that male and female sharks were found sharing the same sponges.</p><p>Choice A is incorrect because the graph shows that one of the sponges (sponge 1) was <em>not</em> inhabited by any undetermined banded sand catsharks. Additionally, this choice doesn&rsquo;t give any information about female sharks, so it can&rsquo;t support the claim that male and female sharks are actually found in the same sponge. Choice B is incorrect because it doesn&rsquo;t give any information about female sharks. The graph does show that approximately 17 male banded sand catsharks inhabited sponge 1, but that information alone can&rsquo;t support the claim that male and female sharks are found in the same sponge. Choice D is incorrect because it doesn&rsquo;t give any information about male banded sand catsharks. The graph does show that approximately 13 female banded sand catsharks inhabited sponge 1, but that information alone can&rsquo;t support the claim that male and female sharks are found in the same sponge.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$6b8a7c74$SATQ$, $SATQ$8555f0c4-2d61-4e72-8296-f46b4e8cad27$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>One recognized social norm of gift giving is that the time spent obtaining a gift will be viewed as a reflection of the gift&rsquo;s thoughtfulness. Marketing experts Farnoush Reshadi, Julian Givi, and Gopal Das addressed this view in their studies of norms specifically surrounding the giving of gift cards, noting that while recipients tend to view digital gift cards (which can be purchased online from anywhere and often can be redeemed online as well) as superior to physical gift cards (which sometimes must be purchased in person and may only be redeemable in person) in terms of usage, 94.8 percent of participants surveyed indicated that it is more socially acceptable to give a physical gift card to a recipient. This finding suggests that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"46d0df11-0ac4-4591-978a-70bafd2b6b72","content":"<p>gift givers likely overestimate the amount of effort required to use digital gift cards and thus mistakenly assume gift recipients will view them as less desirable than physical gift cards.</p>"},{"id":"3261fbe0-d850-47b1-962a-52900b5684db","content":"<p>physical gift cards are likely preferred by gift recipients because the tangible nature of those cards offers a greater psychological sense of ownership than digital gift cards do.</p>"},{"id":"00f9bd97-7b34-479d-9af2-a56849caff21","content":"<p>physical gift cards are likely less desirable to gift recipients than digital gift cards are because of the perception that physical gift cards require unnecessary effort to obtain.</p>"},{"id":"deabb87b-37e2-44fa-9ee0-35d60bc92f6c","content":"<p>gift givers likely perceive digital gift cards as requiring relatively low effort to obtain and thus wrongly assume gift recipients will appreciate them less than they do physical gift cards.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["deabb87b-37e2-44fa-9ee0-35d60bc92f6c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of perceptions of digital versus physical gift cards. The text begins by explaining that the perception of "the time spent obtaining a gift&hellip;as a reflection of the gift&rsquo;s thoughtfulness" is a social norm of gift giving. The text then explains that although those who receive digital gift cards view them as easier to use than physical gift cards, a marketing study nonetheless showed that 94.8% of participants found physical gift cards more "socially acceptable" to give. The text specifically contrasts the ease with which digital gift cards "can be purchased online from anywhere" with the fact that physical gift cards "sometimes must be purchased in person"&mdash;suggesting the greater difficulty of obtaining physical cards. Given the text&rsquo;s initial premise that gift-giving norms equate the thoughtfulness of a gift with the effort involved in acquiring that gift, it is reasonable to infer that people perceive digital gift cards as requiring less effort to obtain and thus assume recipients will appreciate them less, even though recipients actually prefer gift cards in the more usable digital format.</p><p>Choice A is incorrect. Although the text does discuss recipients&rsquo; preference of digital versus physical gift cards and the relative ease with which the two formats can be used, it doesn&rsquo;t consider the misconceptions that gift givers may have of these factors. Moreover, the text establishes that recipients regard digital gift cards as easier to use and therefore preferable to physical gift cards. Choice B is incorrect because the text doesn&rsquo;t consider whether recipients of gift cards feel a sense of ownership toward them, nor does the text touch on the greater tangibility of physical versus digital gift cards. Instead, the text contrasts the two formats of gift cards in terms of their respective usability and the difficulty involved in acquiring them and discusses how those factors influence people&rsquo;s perceptions of the two formats. Choice C is incorrect because it contradicts the text, which explains that recipients regard digital gift cards as superior to physical ones because they are easier to use than physical cards, not because physical gift cards require greater effort to obtain than digital gift cards do. Moreover, the text doesn&rsquo;t characterize the effort required to obtain physical gift cards as "unnecessary."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6b8a7c74","external_id":"8555f0c4-2d61-4e72-8296-f46b4e8cad27","vaultid":null,"uId":"019f007e-98e6-4808-bb30-2197bbd5dc85","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>One recognized social norm of gift giving is that the time spent obtaining a gift will be viewed as a reflection of the gift&rsquo;s thoughtfulness. Marketing experts Farnoush Reshadi, Julian Givi, and Gopal Das addressed this view in their studies of norms specifically surrounding the giving of gift cards, noting that while recipients tend to view digital gift cards (which can be purchased online from anywhere and often can be redeemed online as well) as superior to physical gift cards (which sometimes must be purchased in person and may only be redeemable in person) in terms of usage, 94.8 percent of participants surveyed indicated that it is more socially acceptable to give a physical gift card to a recipient. This finding suggests that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"46d0df11-0ac4-4591-978a-70bafd2b6b72","content":"<p>gift givers likely overestimate the amount of effort required to use digital gift cards and thus mistakenly assume gift recipients will view them as less desirable than physical gift cards.</p>"},{"id":"3261fbe0-d850-47b1-962a-52900b5684db","content":"<p>physical gift cards are likely preferred by gift recipients because the tangible nature of those cards offers a greater psychological sense of ownership than digital gift cards do.</p>"},{"id":"00f9bd97-7b34-479d-9af2-a56849caff21","content":"<p>physical gift cards are likely less desirable to gift recipients than digital gift cards are because of the perception that physical gift cards require unnecessary effort to obtain.</p>"},{"id":"deabb87b-37e2-44fa-9ee0-35d60bc92f6c","content":"<p>gift givers likely perceive digital gift cards as requiring relatively low effort to obtain and thus wrongly assume gift recipients will appreciate them less than they do physical gift cards.</p>"}],"keys":["deabb87b-37e2-44fa-9ee0-35d60bc92f6c"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of perceptions of digital versus physical gift cards. The text begins by explaining that the perception of \"the time spent obtaining a gift&hellip;as a reflection of the gift&rsquo;s thoughtfulness\" is a social norm of gift giving. The text then explains that although those who receive digital gift cards view them as easier to use than physical gift cards, a marketing study nonetheless showed that 94.8% of participants found physical gift cards more \"socially acceptable\" to give. The text specifically contrasts the ease with which digital gift cards \"can be purchased online from anywhere\" with the fact that physical gift cards \"sometimes must be purchased in person\"&mdash;suggesting the greater difficulty of obtaining physical cards. Given the text&rsquo;s initial premise that gift-giving norms equate the thoughtfulness of a gift with the effort involved in acquiring that gift, it is reasonable to infer that people perceive digital gift cards as requiring less effort to obtain and thus assume recipients will appreciate them less, even though recipients actually prefer gift cards in the more usable digital format.</p><p>Choice A is incorrect. Although the text does discuss recipients&rsquo; preference of digital versus physical gift cards and the relative ease with which the two formats can be used, it doesn&rsquo;t consider the misconceptions that gift givers may have of these factors. Moreover, the text establishes that recipients regard digital gift cards as easier to use and therefore preferable to physical gift cards. Choice B is incorrect because the text doesn&rsquo;t consider whether recipients of gift cards feel a sense of ownership toward them, nor does the text touch on the greater tangibility of physical versus digital gift cards. Instead, the text contrasts the two formats of gift cards in terms of their respective usability and the difficulty involved in acquiring them and discusses how those factors influence people&rsquo;s perceptions of the two formats. Choice C is incorrect because it contradicts the text, which explains that recipients regard digital gift cards as superior to physical ones because they are easier to use than physical cards, not because physical gift cards require greater effort to obtain than digital gift cards do. Moreover, the text doesn&rsquo;t characterize the effort required to obtain physical gift cards as \"unnecessary.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061189,"updateDate":1755117061189}$SATQ$::jsonb, 1755117061189, 1755117061189),
    ($SATQ$6bc0e595$SATQ$, $SATQ$83317e04-9b65-4e2e-81f4-ff77cf641a23$SATQ$::uuid, $SATQ$54b53ce0-cff7-4c06-a037-527f0dea776b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>One aspect of in-person shopping that online shopping can&rsquo;t replicate is the opportunity to touch a product before buying it. Does this difference matter? In an experiment, researchers asked one group of participants to touch a mug and a toy, while another group was prohibited from touching the two items. The participants were then asked how much money they&rsquo;d pay for the items. People who got to touch the items were willing to pay much more money for them than were people who weren&rsquo;t allowed to touch the items. This finding suggests that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"c5cb3ed0-4b0d-4b19-97a9-fd3bc210631d","content":"<p>people who mainly shop online probably spend more money every month than people who mainly shop in person do.</p>"},{"id":"e22fbcc0-1c81-4c1d-8357-771c217fd63a","content":"<p>in-person shopping may make products seem more valuable than they seem if only viewed online.&nbsp;</p>"},{"id":"5e75c0ad-f431-4575-a218-fc615aa66e93","content":"<p>retailers with in-person and online stores should charge the same price for a given product in both places.</p>"},{"id":"baabaeff-68aa-438b-b7d6-26829b06164a","content":"<p>online retailers may be able to raise the prices they charge for products that are only available online.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["e22fbcc0-1c81-4c1d-8357-771c217fd63a"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The text tells us that &ldquo;people who got to touch the items were willing to pay much more money for them than people who weren&rsquo;t allowed to touch&rdquo; them. This suggests that being able to interact with a product in person may make it seem more valuable to a shopper. </p><p>Choice A is incorrect. The text doesn&rsquo;t discuss how much people spend each month, so there&rsquo;s not much basis for this claim. Furthermore, since being able to touch a product tends to make people &ldquo;willing to pay much more money&rdquo; for it, we might predict that an online shopper would be willing to spend less on the same purchases as an in-person shopper. Choice C is incorrect. The text doesn&rsquo;t discuss what retailers &ldquo;should charge,&rdquo; so there&rsquo;s not much basis for this claim. Furthermore, the study in the text suggests that in-person stores may actually be able to charge more for a given product, since shoppers can touch it. Choice D is incorrect. The text doesn&rsquo;t discuss products that are only available online, so there&rsquo;s not much basis for this claim. Furthermore, products only available online would still have the problem of shoppers not being able to touch them, and the study suggests that this lowers the prices shoppers are willing to pay. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-E007$SATQ$, $SATQ$$SATQ$, $SATQ$10f0cf3a-dc79-4799-9a00-e099fab864bf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6bc0e595","external_id":"83317e04-9b65-4e2e-81f4-ff77cf641a23","vaultid":"54b53ce0-cff7-4c06-a037-527f0dea776b","uId":"35fbf869-05b7-4b53-b8a4-39d709a0aac2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>One aspect of in-person shopping that online shopping can&rsquo;t replicate is the opportunity to touch a product before buying it. Does this difference matter? In an experiment, researchers asked one group of participants to touch a mug and a toy, while another group was prohibited from touching the two items. The participants were then asked how much money they&rsquo;d pay for the items. People who got to touch the items were willing to pay much more money for them than were people who weren&rsquo;t allowed to touch the items. This finding suggests that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"c5cb3ed0-4b0d-4b19-97a9-fd3bc210631d","content":"<p>people who mainly shop online probably spend more money every month than people who mainly shop in person do.</p>"},{"id":"e22fbcc0-1c81-4c1d-8357-771c217fd63a","content":"<p>in-person shopping may make products seem more valuable than they seem if only viewed online.&nbsp;</p>"},{"id":"5e75c0ad-f431-4575-a218-fc615aa66e93","content":"<p>retailers with in-person and online stores should charge the same price for a given product in both places.</p>"},{"id":"baabaeff-68aa-438b-b7d6-26829b06164a","content":"<p>online retailers may be able to raise the prices they charge for products that are only available online.</p>"}],"keys":["e22fbcc0-1c81-4c1d-8357-771c217fd63a"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The text tells us that &ldquo;people who got to touch the items were willing to pay much more money for them than people who weren&rsquo;t allowed to touch&rdquo; them. This suggests that being able to interact with a product in person may make it seem more valuable to a shopper. </p><p>Choice A is incorrect. The text doesn&rsquo;t discuss how much people spend each month, so there&rsquo;s not much basis for this claim. Furthermore, since being able to touch a product tends to make people &ldquo;willing to pay much more money&rdquo; for it, we might predict that an online shopper would be willing to spend less on the same purchases as an in-person shopper. Choice C is incorrect. The text doesn&rsquo;t discuss what retailers &ldquo;should charge,&rdquo; so there&rsquo;s not much basis for this claim. Furthermore, the study in the text suggests that in-person stores may actually be able to charge more for a given product, since shoppers can touch it. Choice D is incorrect. The text doesn&rsquo;t discuss products that are only available online, so there&rsquo;s not much basis for this claim. Furthermore, products only available online would still have the problem of shoppers not being able to touch them, and the study suggests that this lowers the prices shoppers are willing to pay. </p>","parenttemplatename":"OSP-KA-INF-E007","parenttemplateid":"","templateclusterid":"10f0cf3a-dc79-4799-9a00-e099fab864bf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$6d69ab93$SATQ$, $SATQ$0ce08800-10d9-4d16-a1c0-8564259c6e1f$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Initially observed in 2017, the interstellar object &lsquo;Oumuamua is the first object of its kind to be seen in our solar system. Researchers have been puzzled because its acceleration cannot be entirely explained by the gravitational pull of nearby bodies: there must be a nongravitational influence on its velocity and trajectory. Some previously suggested explanations for this nongravitational acceleration involve mechanisms that are unlikely or unrealistic, such as geometric effects from &lsquo;Oumuamua being potentially composed of several spatially separated bodies. Now, Jennifer Bergner and colleagues propose that the nongravitational acceleration is due to the gaseous expulsion of entrapped hydrogen from &lsquo;Oumuamua&rsquo;s water-rich icy body.</p>$SATQ$, $SATQ$<p>Which statement, if true, would most strongly support the claim made by Bergner and colleagues about the cause of &lsquo;Oumuamua&rsquo;s acceleration?</p>$SATQ$, $SATQ$[{"id":"df851bc2-5f62-48d5-ae5c-c30494a048c5","content":"<p>Existing proposed models of outgassing from &lsquo;Oumuamua include the direct conversion of nitrogen or carbon monoxide from a solid to a gaseous state without becoming liquid, but these models have theoretical or observational inconsistencies.</p>"},{"id":"7996def5-056e-46b3-9e9d-74bf9ee7bae5","content":"<p>&lsquo;Oumuamua&rsquo;s trajectory is inconsistent with a nongravitational acceleration that would be caused by the release of hydrogen gas resulting from the processing of water ice (H<sub>2</sub>O), but the interstellar object&rsquo;s observable properties can be explained if it has a significant component of molecular hydrogen ice (H<sub>2</sub>).</p>"},{"id":"7e663aa6-beae-4ab9-90ff-31a42d50e729","content":"<p>Since nongravitational accelerations of interstellar objects are several orders of magnitude weaker than gravitational accelerations, deviation from behavior that could be fully attributed to gravitational pull has been detected on a limited number of objects similar to &lsquo;Oumuamua.</p>"},{"id":"15bf365a-31d4-4640-86a1-22be89a553f2","content":"<p>Exposure to interstellar cosmic radiation can result in the formation of embedded pockets of hydrogen gas in water ice; moreover, when traveling through the solar system, &lsquo;Oumuamua experienced warming sufficient to alter its icy structure and allow for outgassing.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["15bf365a-31d4-4640-86a1-22be89a553f2"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents findings that, if true, would support the claim made by Bergner and colleagues that the nongravitational acceleration of &lsquo;Oumuamua is due to the expulsion of entrapped hydrogen. The text first introduces the observation of a unique interstellar object named &lsquo;Oumuamua and goes on to explain that the object exhibited nongravitational acceleration that could not be fully attributed to the expected cause: gravitational pull of nearby celestial bodies. The text concludes by stating that Bergner and colleagues claim that the nongravitational acceleration is caused by expulsion of hydrogen gas from &lsquo;Oumuamua&rsquo;s water-rich icy body. To support this claim requires evidence that hydrogen gas could be present within &lsquo;Oumuamua at all, which this answer choice presents: cosmic radiation can result in embedded pockets of hydrogen gas in water ice. Additionally, evidence that this gas can be released from such a body is required to fully support the claim, which this answer choice goes on to provide: &lsquo;Oumuamua experienced sufficient warming as it traveled through the solar system to alter its icy structure and release the hydrogen gas. Thus, this answer choice provides the best evidence to support Bergner and colleagues&rsquo; claim.</p><p>Choice A is incorrect because this answer choice concerns faults with previous models of outgassing from &lsquo;Oumuamua of carbon monoxide and nitrogen, which would not support a claim regarding hydrogen outgassing. Furthermore, inconsistencies in other models would not provide evidence in support of a different model or explanation. Choice B is incorrect. The evidence presented in this answer choice would weaken the claim proposed by Bergner and colleagues that the nongravitational acceleration of &lsquo;Oumuamua is caused by the expulsion of hydrogen gas because this answer choice suggests that there is evidence that refutes this claim: &lsquo;Oumuamua&rsquo;s trajectory is inconsistent with a nongravitational acceleration caused by the release of hydrogen gas. Furthermore, the remaining portion of this answer choice is unrelated to the claim. Choice C is incorrect because the claim being made by Bergner and colleagues concerns the expulsion of entrapped hydrogen gas, but this answer choice is concerned solely with the differences in magnitude of gravitational and nongravitational acceleration, which would not support Bergner&rsquo;s claim. Furthermore, this answer choice discusses interstellar objects similar to &lsquo;Oumuamua, but the text states that &lsquo;Oumuamua is the first observed object of its kind in our solar system, so evidence from other, similar bodies would not be available.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6d69ab93","external_id":"0ce08800-10d9-4d16-a1c0-8564259c6e1f","vaultid":null,"uId":"c881a4c2-936a-4fa3-af93-d7bf0f18fb5f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Initially observed in 2017, the interstellar object &lsquo;Oumuamua is the first object of its kind to be seen in our solar system. Researchers have been puzzled because its acceleration cannot be entirely explained by the gravitational pull of nearby bodies: there must be a nongravitational influence on its velocity and trajectory. Some previously suggested explanations for this nongravitational acceleration involve mechanisms that are unlikely or unrealistic, such as geometric effects from &lsquo;Oumuamua being potentially composed of several spatially separated bodies. Now, Jennifer Bergner and colleagues propose that the nongravitational acceleration is due to the gaseous expulsion of entrapped hydrogen from &lsquo;Oumuamua&rsquo;s water-rich icy body.</p>","stem":"<p>Which statement, if true, would most strongly support the claim made by Bergner and colleagues about the cause of &lsquo;Oumuamua&rsquo;s acceleration?</p>","answerOptions":[{"id":"df851bc2-5f62-48d5-ae5c-c30494a048c5","content":"<p>Existing proposed models of outgassing from &lsquo;Oumuamua include the direct conversion of nitrogen or carbon monoxide from a solid to a gaseous state without becoming liquid, but these models have theoretical or observational inconsistencies.</p>"},{"id":"7996def5-056e-46b3-9e9d-74bf9ee7bae5","content":"<p>&lsquo;Oumuamua&rsquo;s trajectory is inconsistent with a nongravitational acceleration that would be caused by the release of hydrogen gas resulting from the processing of water ice (H<sub>2</sub>O), but the interstellar object&rsquo;s observable properties can be explained if it has a significant component of molecular hydrogen ice (H<sub>2</sub>).</p>"},{"id":"7e663aa6-beae-4ab9-90ff-31a42d50e729","content":"<p>Since nongravitational accelerations of interstellar objects are several orders of magnitude weaker than gravitational accelerations, deviation from behavior that could be fully attributed to gravitational pull has been detected on a limited number of objects similar to &lsquo;Oumuamua.</p>"},{"id":"15bf365a-31d4-4640-86a1-22be89a553f2","content":"<p>Exposure to interstellar cosmic radiation can result in the formation of embedded pockets of hydrogen gas in water ice; moreover, when traveling through the solar system, &lsquo;Oumuamua experienced warming sufficient to alter its icy structure and allow for outgassing.</p>"}],"keys":["15bf365a-31d4-4640-86a1-22be89a553f2"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents findings that, if true, would support the claim made by Bergner and colleagues that the nongravitational acceleration of &lsquo;Oumuamua is due to the expulsion of entrapped hydrogen. The text first introduces the observation of a unique interstellar object named &lsquo;Oumuamua and goes on to explain that the object exhibited nongravitational acceleration that could not be fully attributed to the expected cause: gravitational pull of nearby celestial bodies. The text concludes by stating that Bergner and colleagues claim that the nongravitational acceleration is caused by expulsion of hydrogen gas from &lsquo;Oumuamua&rsquo;s water-rich icy body. To support this claim requires evidence that hydrogen gas could be present within &lsquo;Oumuamua at all, which this answer choice presents: cosmic radiation can result in embedded pockets of hydrogen gas in water ice. Additionally, evidence that this gas can be released from such a body is required to fully support the claim, which this answer choice goes on to provide: &lsquo;Oumuamua experienced sufficient warming as it traveled through the solar system to alter its icy structure and release the hydrogen gas. Thus, this answer choice provides the best evidence to support Bergner and colleagues&rsquo; claim.</p><p>Choice A is incorrect because this answer choice concerns faults with previous models of outgassing from &lsquo;Oumuamua of carbon monoxide and nitrogen, which would not support a claim regarding hydrogen outgassing. Furthermore, inconsistencies in other models would not provide evidence in support of a different model or explanation. Choice B is incorrect. The evidence presented in this answer choice would weaken the claim proposed by Bergner and colleagues that the nongravitational acceleration of &lsquo;Oumuamua is caused by the expulsion of hydrogen gas because this answer choice suggests that there is evidence that refutes this claim: &lsquo;Oumuamua&rsquo;s trajectory is inconsistent with a nongravitational acceleration caused by the release of hydrogen gas. Furthermore, the remaining portion of this answer choice is unrelated to the claim. Choice C is incorrect because the claim being made by Bergner and colleagues concerns the expulsion of entrapped hydrogen gas, but this answer choice is concerned solely with the differences in magnitude of gravitational and nongravitational acceleration, which would not support Bergner&rsquo;s claim. Furthermore, this answer choice discusses interstellar objects similar to &lsquo;Oumuamua, but the text states that &lsquo;Oumuamua is the first observed object of its kind in our solar system, so evidence from other, similar bodies would not be available.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$6df33868$SATQ$, $SATQ$cc8be552-4528-4487-9a80-6ef3a7490aff$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>&nbsp;&ldquo;We Are Marching&rdquo; is a 1921 poem by Carrie Law Morgan Figgs. In the poem, the speaker predicts future success: <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;We Are Marching&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"55697fea-b515-4270-ad21-a8606c2f7145","content":"<p>&ldquo;Can&rsquo;t you hear the sound of feet?&rdquo;</p>"},{"id":"0c482a10-b3ff-44f0-9d1b-d90095cbb01d","content":"<p>&ldquo;You who are out just get in line.&rdquo;&nbsp;</p>"},{"id":"a6f2af19-b0e9-4069-ae80-08c77d1b8094","content":"<p>&ldquo;We have answered duty&rsquo;s call.&rdquo;</p>"},{"id":"ca42d725-f6f2-4265-b375-a7260d88a836","content":"<p>&ldquo;We shall never know defeat.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["ca42d725-f6f2-4265-b375-a7260d88a836"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most effectively illustrates the claim that the speaker in the poem "We Are Marching" predicts future success. To say that someone will "never know" an experience&mdash;like defeat, or being unsuccessful&mdash;is to indicate that they will never personally have that experience. Thus, when the speaker says that the marching group "shall never know defeat," the speaker is predicting that the group will experience only success in the future.</p><p>Choice A is incorrect because the quotation presents a question about an activity already taking place (marching), not a statement about future success. The speaker is asking if the sound of marching feet is being heard. Choice B is incorrect because the quotation directs an immediate action instead of making a prediction about the future. The speaker is telling people to "get in line," or to join the march that&rsquo;s already happening. Choice C is incorrect because the quotation describes a past action instead of making a prediction about the future. The speaker is stating that those in the march have "answered duty&rsquo;s call"&mdash;that is, that they have acted out of a sense of duty.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"6df33868","external_id":"cc8be552-4528-4487-9a80-6ef3a7490aff","vaultid":null,"uId":"292b2702-88e6-4a5f-90e8-5573f0199931","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>&nbsp;&ldquo;We Are Marching&rdquo; is a 1921 poem by Carrie Law Morgan Figgs. In the poem, the speaker predicts future success: <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;We Are Marching&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"55697fea-b515-4270-ad21-a8606c2f7145","content":"<p>&ldquo;Can&rsquo;t you hear the sound of feet?&rdquo;</p>"},{"id":"0c482a10-b3ff-44f0-9d1b-d90095cbb01d","content":"<p>&ldquo;You who are out just get in line.&rdquo;&nbsp;</p>"},{"id":"a6f2af19-b0e9-4069-ae80-08c77d1b8094","content":"<p>&ldquo;We have answered duty&rsquo;s call.&rdquo;</p>"},{"id":"ca42d725-f6f2-4265-b375-a7260d88a836","content":"<p>&ldquo;We shall never know defeat.&rdquo;</p>"}],"keys":["ca42d725-f6f2-4265-b375-a7260d88a836"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most effectively illustrates the claim that the speaker in the poem \"We Are Marching\" predicts future success. To say that someone will \"never know\" an experience&mdash;like defeat, or being unsuccessful&mdash;is to indicate that they will never personally have that experience. Thus, when the speaker says that the marching group \"shall never know defeat,\" the speaker is predicting that the group will experience only success in the future.</p><p>Choice A is incorrect because the quotation presents a question about an activity already taking place (marching), not a statement about future success. The speaker is asking if the sound of marching feet is being heard. Choice B is incorrect because the quotation directs an immediate action instead of making a prediction about the future. The speaker is telling people to \"get in line,\" or to join the march that&rsquo;s already happening. Choice C is incorrect because the quotation describes a past action instead of making a prediction about the future. The speaker is stating that those in the march have \"answered duty&rsquo;s call\"&mdash;that is, that they have acted out of a sense of duty.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061192,"updateDate":1755117061192}$SATQ$::jsonb, 1755117061192, 1755117061192),
    ($SATQ$6e0e0de1$SATQ$, $SATQ$dd2f579c-787f-4760-a6c3-d9cf6f9de19e$SATQ$::uuid, $SATQ$c193b65e-7b9c-490d-a952-d0763df7d858$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Aerogels are highly porous foams consisting mainly of tiny air pockets within a solidified gel. These lightweight materials are often applied to spacecraft and other equipment required to withstand extreme conditions, as they provide excellent insulation despite typically being brittle and eventually fracturing due to degradation from repeated exposure to high heat. Now, Xiangfeng Duan of the University of California, Los Angeles, and colleagues have developed an aerogel with uniquely flexible properties. Unlike earlier aerogels, Duan&rsquo;s team&rsquo;s material contracts rather than expands when heated and fully recovers after compressing to just 5% of its original volume, suggesting that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"9d0ed868-8d5c-4aeb-9ccf-4067f5c8b703","content":"<p>the aerogel&rsquo;s remarkable flexibility results from its higher proportion of air pockets to solidified gel as compared to other aerogels.</p>"},{"id":"293ae07e-bd75-428e-8efa-67fb53ec8104","content":"<p>the aerogel&rsquo;s overall strength is greater than that of other insulators but its ability to withstand exposure to intense heat is lower.</p>"},{"id":"a9a0f9ea-9b18-4a68-8994-6f451f534e3a","content":"<p>the aerogel will be more effective as an insulator for uses that involve gradual temperature shifts than for those that involve rapid heat increases.</p>"},{"id":"0e385f0f-986a-4243-aa8e-b2c9d1f5463f","content":"<p>the aerogel will be less prone to the structural weakness that ultimately causes most other aerogels to break down with use.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["0e385f0f-986a-4243-aa8e-b2c9d1f5463f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of aerogels. The text states that aerogels&mdash;highly porous foams&mdash;offer "excellent insulation" but typically break down after prolonged exposure to high heat. However, according to the text, Duan and colleagues developed an aerogel that "contracts rather than expands when heated" and recovers its original volume after this contraction. Thus, it is logical to conclude that Duan&rsquo;s team&rsquo;s aerogel material will be less prone to the structural weakness that caused earlier aerogels to break down.</p><p>Choice A is incorrect. Although the text indicates that aerogels consist "mainly of tiny air pockets within a solidified gel," it doesn&rsquo;t mention the number or proportion of air pockets to solidified gel in typical aerogels or in the aerogel developed by Duan&rsquo;s team. Choice B is incorrect because the text suggests that the aerogel developed by Duan&rsquo;s team has a higher, not a lower, ability to withstand exposure to intense heat due to its contraction and subsequent recovery. Choice C is incorrect. Although the text discusses temperature tolerances of aerogels and says that they offer "excellent insulation despite typically being brittle and eventually fracturing," it doesn&rsquo;t discuss how different rates of temperature change can affect aerogels.</p>$SATQ$, false, 0, $SATQ$OSP-060-INF$SATQ$, $SATQ$$SATQ$, $SATQ$d3da4584-9a31-42dc-bbe2-3b8a5a0ad736$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"6e0e0de1","external_id":"dd2f579c-787f-4760-a6c3-d9cf6f9de19e","vaultid":"c193b65e-7b9c-490d-a952-d0763df7d858","uId":"b2fd6519-a045-4410-b6c4-13857b794eb2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Aerogels are highly porous foams consisting mainly of tiny air pockets within a solidified gel. These lightweight materials are often applied to spacecraft and other equipment required to withstand extreme conditions, as they provide excellent insulation despite typically being brittle and eventually fracturing due to degradation from repeated exposure to high heat. Now, Xiangfeng Duan of the University of California, Los Angeles, and colleagues have developed an aerogel with uniquely flexible properties. Unlike earlier aerogels, Duan&rsquo;s team&rsquo;s material contracts rather than expands when heated and fully recovers after compressing to just 5% of its original volume, suggesting that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"9d0ed868-8d5c-4aeb-9ccf-4067f5c8b703","content":"<p>the aerogel&rsquo;s remarkable flexibility results from its higher proportion of air pockets to solidified gel as compared to other aerogels.</p>"},{"id":"293ae07e-bd75-428e-8efa-67fb53ec8104","content":"<p>the aerogel&rsquo;s overall strength is greater than that of other insulators but its ability to withstand exposure to intense heat is lower.</p>"},{"id":"a9a0f9ea-9b18-4a68-8994-6f451f534e3a","content":"<p>the aerogel will be more effective as an insulator for uses that involve gradual temperature shifts than for those that involve rapid heat increases.</p>"},{"id":"0e385f0f-986a-4243-aa8e-b2c9d1f5463f","content":"<p>the aerogel will be less prone to the structural weakness that ultimately causes most other aerogels to break down with use.</p>"}],"keys":["0e385f0f-986a-4243-aa8e-b2c9d1f5463f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of aerogels. The text states that aerogels&mdash;highly porous foams&mdash;offer \"excellent insulation\" but typically break down after prolonged exposure to high heat. However, according to the text, Duan and colleagues developed an aerogel that \"contracts rather than expands when heated\" and recovers its original volume after this contraction. Thus, it is logical to conclude that Duan&rsquo;s team&rsquo;s aerogel material will be less prone to the structural weakness that caused earlier aerogels to break down.</p><p>Choice A is incorrect. Although the text indicates that aerogels consist \"mainly of tiny air pockets within a solidified gel,\" it doesn&rsquo;t mention the number or proportion of air pockets to solidified gel in typical aerogels or in the aerogel developed by Duan&rsquo;s team. Choice B is incorrect because the text suggests that the aerogel developed by Duan&rsquo;s team has a higher, not a lower, ability to withstand exposure to intense heat due to its contraction and subsequent recovery. Choice C is incorrect. Although the text discusses temperature tolerances of aerogels and says that they offer \"excellent insulation despite typically being brittle and eventually fracturing,\" it doesn&rsquo;t discuss how different rates of temperature change can affect aerogels.</p>","parenttemplatename":"OSP-060-INF","parenttemplateid":"","templateclusterid":"d3da4584-9a31-42dc-bbe2-3b8a5a0ad736","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::jsonb, 1691007959325, 1691007959325),
    ($SATQ$6f626ae5$SATQ$, $SATQ$8f0c9a99-086b-4120-9d4c-96146f022bdc$SATQ$::uuid, $SATQ$03efd007-df90-4849-b0f8-06d6647477ce$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>&ldquo;To You&rdquo; is an 1856 poem by Walt Whitman. In the poem, Whitman suggests that readers, whom he addresses directly, have not fully understood themselves, writing, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which quotation from &ldquo;To You&rdquo; most effectively illustrates the claim?</p>$SATQ$, $SATQ$[{"id":"2774abe2-42da-473d-a8e2-47935ebe28ad","content":"<p>&ldquo;You have not known what you are, you have slumber&rsquo;d upon yourself / all your life, / Your eyelids have been the same as closed most of the time.&rdquo;</p>"},{"id":"182e0b35-b351-4598-91b8-79fe717020a9","content":"<p>&ldquo;These immense meadows, these interminable rivers, you are immense / and interminable as they.&rdquo;</p>"},{"id":"db8a9ac2-6e22-41c8-96f4-16a1943e43c3","content":"<p>&ldquo;I should have made my way straight to you long ago, / I should have blabb&rsquo;d nothing but you, I should have chanted nothing / but you.&rdquo;</p>"},{"id":"4f1f7e54-618c-475e-aeac-1e6f96b9d946","content":"<p>&ldquo;I will leave all and come and make the hymns of you, / None has understood you, but I understand you.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["2774abe2-42da-473d-a8e2-47935ebe28ad"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it presents the quotation that most directly illustrates the claim that Whitman&rsquo;s poem suggests that its readers haven&rsquo;t fully understood themselves. This quotation makes that point directly by saying to readers, &ldquo;You have not known what you are.&rdquo; The quotation goes on to reinforce this point using a metaphor of sleep, saying that readers have &ldquo;slumber&rsquo;d&rdquo; and that their &ldquo;eyelids have been the same as closed most of the time.&rdquo;&nbsp;</p><p>Choice B is incorrect because this quotation doesn&rsquo;t suggest that readers haven&rsquo;t fully understood themselves but instead characterizes readers as &ldquo;immense&rdquo; and &ldquo;interminable.&rdquo; Although immense and interminable things can be difficult to understand, this quotation doesn&rsquo;t make that point.&nbsp;Choice C is incorrect because this quotation doesn&rsquo;t suggest that readers haven&rsquo;t fully understood themselves but instead conveys the speaker&rsquo;s regret over not having celebrated readers sooner. In fact, this quotation says nothing at all about readers themselves&mdash;it&rsquo;s focused solely on the speaker&rsquo;s feelings about readers.&nbsp;Choice D is incorrect because this quotation doesn&rsquo;t suggest that readers haven&rsquo;t fully understood themselves; instead, this quotation makes the point that the speaker has understood readers and is determined to create &ldquo;hymns&rdquo; about them. </p>$SATQ$, false, 0, $SATQ$P89-T036$SATQ$, $SATQ$$SATQ$, $SATQ$bfa6259d-a12b-4b83-a58d-3e31c1ed8365$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$1$SATQ$, NULL, NULL, $SATQ${"questionId":"6f626ae5","external_id":"8f0c9a99-086b-4120-9d4c-96146f022bdc","vaultid":"03efd007-df90-4849-b0f8-06d6647477ce","uId":"1ac61d5d-0f39-4ab8-ad2c-90989e40a1ed","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>&ldquo;To You&rdquo; is an 1856 poem by Walt Whitman. In the poem, Whitman suggests that readers, whom he addresses directly, have not fully understood themselves, writing, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which quotation from &ldquo;To You&rdquo; most effectively illustrates the claim?</p>","answerOptions":[{"id":"2774abe2-42da-473d-a8e2-47935ebe28ad","content":"<p>&ldquo;You have not known what you are, you have slumber&rsquo;d upon yourself / all your life, / Your eyelids have been the same as closed most of the time.&rdquo;</p>"},{"id":"182e0b35-b351-4598-91b8-79fe717020a9","content":"<p>&ldquo;These immense meadows, these interminable rivers, you are immense / and interminable as they.&rdquo;</p>"},{"id":"db8a9ac2-6e22-41c8-96f4-16a1943e43c3","content":"<p>&ldquo;I should have made my way straight to you long ago, / I should have blabb&rsquo;d nothing but you, I should have chanted nothing / but you.&rdquo;</p>"},{"id":"4f1f7e54-618c-475e-aeac-1e6f96b9d946","content":"<p>&ldquo;I will leave all and come and make the hymns of you, / None has understood you, but I understand you.&rdquo;</p>"}],"keys":["2774abe2-42da-473d-a8e2-47935ebe28ad"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it presents the quotation that most directly illustrates the claim that Whitman&rsquo;s poem suggests that its readers haven&rsquo;t fully understood themselves. This quotation makes that point directly by saying to readers, &ldquo;You have not known what you are.&rdquo; The quotation goes on to reinforce this point using a metaphor of sleep, saying that readers have &ldquo;slumber&rsquo;d&rdquo; and that their &ldquo;eyelids have been the same as closed most of the time.&rdquo;&nbsp;</p><p>Choice B is incorrect because this quotation doesn&rsquo;t suggest that readers haven&rsquo;t fully understood themselves but instead characterizes readers as &ldquo;immense&rdquo; and &ldquo;interminable.&rdquo; Although immense and interminable things can be difficult to understand, this quotation doesn&rsquo;t make that point.&nbsp;Choice C is incorrect because this quotation doesn&rsquo;t suggest that readers haven&rsquo;t fully understood themselves but instead conveys the speaker&rsquo;s regret over not having celebrated readers sooner. In fact, this quotation says nothing at all about readers themselves&mdash;it&rsquo;s focused solely on the speaker&rsquo;s feelings about readers.&nbsp;Choice D is incorrect because this quotation doesn&rsquo;t suggest that readers haven&rsquo;t fully understood themselves; instead, this quotation makes the point that the speaker has understood readers and is determined to create &ldquo;hymns&rdquo; about them. </p>","parenttemplatename":"P89-T036","parenttemplateid":"","templateclusterid":"bfa6259d-a12b-4b83-a58d-3e31c1ed8365","templateclustername":"","origin":"proteus","position":"1","createDate":1691007959378,"updateDate":1691007959378}$SATQ$::jsonb, 1691007959378, 1691007959378),
    ($SATQ$701126bc$SATQ$, $SATQ$9881a760-f884-4181-a7f8-4ee2b2cb39a3$SATQ$::uuid, $SATQ$f9df40bb-5fcd-4ce1-810d-1f8b263f6db7$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$CID$SATQ$, $SATQ$Central Ideas and Details$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In superfluorescence, electrical charges known as dipoles emit light in synchronized bursts so intense that they are visible to the eye. Until recently, this phenomenon has only been observed at extremely cold temperatures because dipoles cannot synchronize at higher temperatures. But in a study, Melike Biliroglu and colleagues observed superfluorescence at room temperature in thin films made of perovskite and other similarly crystalline materials; the researchers propose that the formation of shock-absorbing quasiparticles called polarons in the material protects dipoles from thermal interference.</p>$SATQ$, $SATQ$<p>Based on the text, how are polarons believed to be involved in the superfluorescence observed in Biliroglu and colleagues&rsquo; study?</p>$SATQ$, $SATQ$[{"id":"3e622c95-f10c-4304-b4d4-6752fe829b02","content":"<p>Polarons enable superfluorescent bursts to cross from one crystalline material to another.</p>"},{"id":"171a550d-5ed6-46f4-9823-a5d916f090ac","content":"<p>Polarons allow for the dipoles to synchronize despite higher temperatures.&nbsp;</p>"},{"id":"4181c0bb-7f72-42fc-8207-78b9e8667f22","content":"<p>Polarons accelerate the dipoles&rsquo; release of superfluorescent bursts.</p>"},{"id":"6343a424-617b-4251-bd04-601b178dd7b8","content":"<p>Polarons decrease the intensity of the superfluorescent burst.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["171a550d-5ed6-46f4-9823-a5d916f090ac"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes Biliroglu and colleagues&rsquo; claim about how the polarons function in relation to superfluorescence. The text indicates that &ldquo;until recently,&rdquo; superfluorescence (intense, synchronized bursts of light emitted by dipoles) has solely been observed at very cold temperatures. However, it also states that, recently, Biliroglu and colleagues report observing the phenomenon at room temperature. They achieved this using &ldquo;thin films made of perovskite and other similarly crystalline materials,&rdquo; which the researchers claim allows for the formation of polarons. They also suggest that these polarons might absorb the thermal shocks that typically disrupt dipole synchronization at warmer temperatures. Thus, based on the text, Biliroglu and colleagues believe that polarons help dipoles synchronize at temperatures well above those at which superfluorescence had previously been observed. </p><p>Choice A is incorrect because the text doesn&rsquo;t address the prospect of a superfluorescent burst moving between crystalline materials or any other mediums. Choice C is incorrect because the text&rsquo;s discussion of polarons is about how they might enable superfluorescence at higher temperatures than those at which it had previously been observed. Rather than suggesting that polarons speed up superfluorescent bursts, the text suggests that no superfluorescence can occur at room temperature in the absence of polarons. Thus, the text indicates that polarons make superfluorescent bursts more likely to occur at higher temperatures than those at which it had previously been observed, not that polarons accelerate the bursts. Choice D is incorrect because the text&rsquo;s discussion of polarons is about how they might enable superfluorescence at higher temperatures than those at which it had previously been observed. In the absence of polarons, the text suggests there would be no superfluorescence at room temperature. Thus, rather than decrease the intensity of superfluorescent bursts, polarons make them more likely to occur under certain circumstances.&nbsp;&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-043-CID$SATQ$, $SATQ$$SATQ$, $SATQ$a015b85f-ff22-4bf1-9d44-14ae35833352$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"701126bc","external_id":"9881a760-f884-4181-a7f8-4ee2b2cb39a3","vaultid":"f9df40bb-5fcd-4ce1-810d-1f8b263f6db7","uId":"1ee627bc-0c5a-4d58-91f4-a935f67f921d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"CID","skill_desc":"Central Ideas and Details","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In superfluorescence, electrical charges known as dipoles emit light in synchronized bursts so intense that they are visible to the eye. Until recently, this phenomenon has only been observed at extremely cold temperatures because dipoles cannot synchronize at higher temperatures. But in a study, Melike Biliroglu and colleagues observed superfluorescence at room temperature in thin films made of perovskite and other similarly crystalline materials; the researchers propose that the formation of shock-absorbing quasiparticles called polarons in the material protects dipoles from thermal interference.</p>","stem":"<p>Based on the text, how are polarons believed to be involved in the superfluorescence observed in Biliroglu and colleagues&rsquo; study?</p>","answerOptions":[{"id":"3e622c95-f10c-4304-b4d4-6752fe829b02","content":"<p>Polarons enable superfluorescent bursts to cross from one crystalline material to another.</p>"},{"id":"171a550d-5ed6-46f4-9823-a5d916f090ac","content":"<p>Polarons allow for the dipoles to synchronize despite higher temperatures.&nbsp;</p>"},{"id":"4181c0bb-7f72-42fc-8207-78b9e8667f22","content":"<p>Polarons accelerate the dipoles&rsquo; release of superfluorescent bursts.</p>"},{"id":"6343a424-617b-4251-bd04-601b178dd7b8","content":"<p>Polarons decrease the intensity of the superfluorescent burst.</p>"}],"keys":["171a550d-5ed6-46f4-9823-a5d916f090ac"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes Biliroglu and colleagues&rsquo; claim about how the polarons function in relation to superfluorescence. The text indicates that &ldquo;until recently,&rdquo; superfluorescence (intense, synchronized bursts of light emitted by dipoles) has solely been observed at very cold temperatures. However, it also states that, recently, Biliroglu and colleagues report observing the phenomenon at room temperature. They achieved this using &ldquo;thin films made of perovskite and other similarly crystalline materials,&rdquo; which the researchers claim allows for the formation of polarons. They also suggest that these polarons might absorb the thermal shocks that typically disrupt dipole synchronization at warmer temperatures. Thus, based on the text, Biliroglu and colleagues believe that polarons help dipoles synchronize at temperatures well above those at which superfluorescence had previously been observed. </p><p>Choice A is incorrect because the text doesn&rsquo;t address the prospect of a superfluorescent burst moving between crystalline materials or any other mediums. Choice C is incorrect because the text&rsquo;s discussion of polarons is about how they might enable superfluorescence at higher temperatures than those at which it had previously been observed. Rather than suggesting that polarons speed up superfluorescent bursts, the text suggests that no superfluorescence can occur at room temperature in the absence of polarons. Thus, the text indicates that polarons make superfluorescent bursts more likely to occur at higher temperatures than those at which it had previously been observed, not that polarons accelerate the bursts. Choice D is incorrect because the text&rsquo;s discussion of polarons is about how they might enable superfluorescence at higher temperatures than those at which it had previously been observed. In the absence of polarons, the text suggests there would be no superfluorescence at room temperature. Thus, rather than decrease the intensity of superfluorescent bursts, polarons make them more likely to occur under certain circumstances.&nbsp;&nbsp;</p>","parenttemplatename":"OSP-043-CID","parenttemplateid":"","templateclusterid":"a015b85f-ff22-4bf1-9d44-14ae35833352","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959322,"updateDate":1691007959322}$SATQ$::jsonb, 1691007959322, 1691007959322),
    ($SATQ$702eb7e3$SATQ$, $SATQ$71c4f33b-5e73-413d-bea3-14225980d694$SATQ$::uuid, $SATQ$27ec2b25-82b8-4606-83e4-cd4a450b92e7$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg aria-label="Bar graph titled Economic Policy Uncertainty in the United Kingdom, 2005 to 2010. The horizontal axis is labeled Year. 6 data categories are shown. The vertical axis is labeled Uncertainty (larger values equals more uncertainty). Refer to long description." height="494.590576171875" role="img" viewbox="0 0 400 494.590576171875" width="400" xmlns="http://www.w3.org/2000/svg"><g data-name="Layer 1" id="ed420550-79eb-48d4-af01-cd27cdd08afd"><defs>
